using System;
using System.Linq;
using System.Collections.Generic;

class Program
{
    static void Main()
    {
        var players = new List<Player>
        {
            new Player("Азиз", 80),
            new Player("Тимур", 95),
            new Player("Сара", 60)
        };

        // Тот же смысл, что SELECT Name FROM players WHERE Hp > 70 ORDER BY Hp DESC
        var strong = players
            .Where(p => p.Hp > 70)
            .OrderByDescending(p => p.Hp)
            .Select(p => p.Name);

        foreach (var name in strong)
            Console.WriteLine(name);      // Тимур, Азиз

        Console.WriteLine($"Средний HP: {players.Average(p => p.Hp)}");
    }
}

