using System;

class Account
{
    public int Balance { get; private set; }   // читать всем, менять - только классу

    public Account(int start)
    {
        Balance = start;
    }

    public void Deposit(int amount)
    {
        if (amount > 0) Balance += amount;
    }

    public void Withdraw(int amount)
    {
        if (amount > 0 && amount <= Balance) Balance -= amount;
    }
}

class Program
{
    static void Main()
    {
        var acc = new Account(100);
        acc.Deposit(50);
        acc.Withdraw(200);          // больше баланса - операция игнорируется
        Console.WriteLine(acc.Balance);   // 150
    }
}

