class Program
{
    static void Main()
    {
        string[] words = { "csharp", "sql", "csharp" };

        var counts = words
            .GroupBy(w => w)                                  // GROUP BY word
            .Select(g => new { Word = g.Key, Count = g.Count() })
            .OrderByDescending(x => x.Count);

        foreach (var item in counts)
            Console.WriteLine($"{item.Word}: {item.Count}");   // csharp: 2, sql: 1
    }
}

