using System;
using System.Collections.Generic;

// собственный обобщённый тип: стопка чего угодно
class Stack<T>
{
    private readonly List<T> items = new List<T>();

    public int Count => items.Count;

    public void Push(T item) => items.Add(item);

    public T Pop()
    {
        if (items.Count == 0)
            throw new InvalidOperationException("стопка пуста");
        T last = items[items.Count - 1];
        items.RemoveAt(items.Count - 1);
        return last;
    }
}

// обобщённый метод с ограничением: T должен уметь сравнивать себя
static class Util
{
    public static T Max<T>(T a, T b) where T : IComparable<T>
        => a.CompareTo(b) >= 0 ? a : b;
}

class Program
{
    static void Main()
    {
        var numbers = new Stack<int>();
        numbers.Push(1);
        numbers.Push(2);
        Console.WriteLine(numbers.Pop());     // 2
        Console.WriteLine(numbers.Count);     // 1

        var words = new Stack<string>();      // тот же класс, другой тип
        words.Push("привет");
        Console.WriteLine(words.Pop());       // привет

        Console.WriteLine(Util.Max(3, 7));            // 7
        Console.WriteLine(Util.Max("яблоко", "груша"));  // яблоко
    }
}

using System;

class Program
{
    // ожидаемая ситуация: обрабатываем без исключений
    static int ParseAge(string input)
    {
        if (int.TryParse(input, out int age) && age >= 0 && age <= 130)
            return age;
        return -1;              // -1 значит «не разобрали»
    }

    // исключительная ситуация: сообщаем наверх
    static int Divide(int a, int b)
    {
        if (b == 0)
            throw new ArgumentException("деление на ноль");
        return a / b;
    }

    static void Main()
    {
        Console.WriteLine(ParseAge("42"));       // 42
        Console.WriteLine(ParseAge("сорок"));    // -1
        Console.WriteLine(ParseAge("500"));      // -1

        try
        {
            Console.WriteLine(Divide(10, 2));
            Console.WriteLine(Divide(1, 0));
        }
        catch (ArgumentException e)              // ловим конкретный тип
        {
            Console.WriteLine($"поймали: {e.Message}");
        }
        finally
        {
            Console.WriteLine("finally выполняется всегда");
        }
    }
}

