    {
        var a = new Point(1, 2);
        var b = new Point(1, 2);
        Console.WriteLine(a == b);            // True: сравнение по значению
        Console.WriteLine(a);                 // Point { X = 1, Y = 2 }

        var c = a with { Y = 99 };            // копия с изменением одного поля
        Console.WriteLine(c);                 // Point { X = 1, Y = 99 }
        Console.WriteLine(a);                 // исходная не изменилась

        var p1 = new PointClass(1, 2);
        var p2 = new PointClass(1, 2);
        Console.WriteLine(p1 == p2);          // False: разные объекты
