using System;
using System.Collections.Generic;

class Program
{
    static Dictionary<string, int> Count(string[] words)
    {
        var result = new Dictionary<string, int>();
        foreach (var word in words)
        {
            var key = word.ToLower();
            // TryGetValue вместо обращения по ключу: отсутствующий ключ не бросит
            result.TryGetValue(key, out int seen);
            result[key] = seen + 1;
        }
        return result;
    }

    static void Main()
    {
        var words = new[] { "Код", "тест", "код", "КОД", "тест" };
        var counts = Count(words);

        Console.WriteLine(counts.Count);
        Console.WriteLine(counts["код"]);
    }
}

