using System;

class Pair<T>
{
    public T First { get; }
    public T Second { get; }

    public Pair(T first, T second)
    {
        First = first;
        Second = second;
    }

    // возвращаем новую пару: исходная остаётся нетронутой
    public Pair<T> Swap() => new Pair<T>(Second, First);
}

class Program
{
    static void Main()
    {
        var numbers = new Pair<int>(1, 2);
        Console.WriteLine(numbers.First);

        var swapped = numbers.Swap();
        Console.WriteLine(swapped.First);
        Console.WriteLine(numbers.First);

        var words = new Pair<string>("да", "нет");
        Console.WriteLine(words.Swap().First);
    }
}

